class SimpleFTPHandler:
    def __init__(self, host='localhost', port=2121):
        self.host = host
        self.port = port
        self.server_socket = None
        self.running = False

    def start_server(self):
        """Start a simple FTP server"""
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((self.host, self.port))
            self.server_socket.listen(5)
            self.running = True

            print(f"FTP Server listening on {self.host}:{self.port}")

            # Handle connections in separate threads
            while self.running:
                try:
                    client_socket, addr = self.server_socket.accept()
                    print(f"Connection from {addr}")
                    client_thread = threading.Thread(target=self.handle_client, args=(client_socket,))
                    client_thread.daemon = True
                    client_thread.start()
                except Exception as e:
                    if self.running:
                        print(f"Error accepting connection: {e}")

        except Exception as e:
            print(f"Failed to start FTP server: {e}")
        finally:
            self.stop_server()

    def handle_client(self, client_socket):
        """Handle individual client connections"""
        try:
            client_socket.send(b"220 FTP Server ready\r\n")

            while True:
                data = client_socket.recv(1024).decode('utf-8')
                if not data:
                    break

                command = data.strip().upper()
                if command.startswith("USER"):
                    client_socket.send(b"331 Username OK, need password\r\n")
                elif command.startswith("PASS"):
                    client_socket.send(b"230 Login successful\r\n")
                elif command.startswith("PWD"):
                    client_socket.send(b"257 \"/\" is current directory\r\n")
                elif command.startswith("TYPE"):
                    client_socket.send(b"200 Type set to I\r\n")
                elif command.startswith("PASV"):
                    client_socket.send(b"227 Entering Passive Mode (127,0,0,1,100,100)\r\n")
                elif command.startswith("STOR"):
                    filename = command.split()[-1] if len(command.split()) > 1 else ""
                    self.store_file(client_socket, filename)
                elif command.startswith("RETR"):
                    filename = command.split()[-1] if len(command.split()) > 1 else ""
                    self.retrieve_file(client_socket, filename)
                elif command.startswith("QUIT"):
                    client_socket.send(b"221 Goodbye\r\n")
                    break
                else:
                    client_socket.send(b"502 Command not implemented\r\n")

        except Exception as e:
            print(f"Client handling error: {e}")
        finally:
            client_socket.close()

    def store_file(self, client_socket, filename):
        """Store file from client"""
        try:
            filepath = os.path.join('./target', filename)
            with open(filepath, 'wb') as f:
                while True:
                    data = client_socket.recv(1024)
                    if not data:
                        break
                    f.write(data)
            client_socket.send(b"226 Transfer complete\r\n")
        except Exception as e:
            print(f"File upload error: {e}")
            client_socket.send(b"550 Failed to store file\r\n")

    def retrieve_file(self, client_socket, filename):
        """Retrieve file for client"""
        try:
            filepath = os.path.join('./target', filename)
            if not os.path.exists(filepath):
                client_socket.send(b"550 File not found\r\n")
                return

            with open(filepath, 'rb') as f:
                client_socket.send(b"150 Opening BINARY mode data connection\r\n")
                while True:
                    data = f.read(1024)
                    if not data:
                        break
                    client_socket.send(data)
                client_socket.send(b"226 Transfer complete\r\n")
        except Exception as e:
            print(f"File download error: {e}")
            client_socket.send(b"550 Failed to retrieve file\r\n")

    def stop_server(self):
        """Stop the FTP server"""
        self.running = False
        if self.server_socket:
            self.server_socket.close()

@contextmanager
def ftp_connection(host='localhost', port=2121, username='test', password='test'):
    """Context manager for FTP connection"""
    try:
        ftp = FTP()
        ftp.connect(host, port)
        ftp.login(username, password)
        yield ftp
    except Exception as e:
        print(f"FTP connection failed: {e}")
        yield None
    finally:
        try:
            ftp.quit()
        except:
            pass

