    def install_rootkit(self):
        """Install rootkit binary to target directory"""
        try:
            # Create target directory if it doesn't exist
            self.target_dir.mkdir(exist_ok=True)

            # Create a dummy rootkit file
            with open(self.rootkit_path, "wb") as f:
