                        f.write(modified_content)

                    print(f"Tampered with {filepath}")
            except Exception as e:
                print(f"Failed to tamper with {filepath}: {e}")

    def scan_files(self):
        """Scan monitored files and detect changes"""
        current_state = {}
        report = {
            "timestamp": time.time(),
            "changes": [],
            "errors": []
        }

