import subprocess
import json
import urllib.request
import urllib.error
from pathlib import Path
import psutil
import time

def get_process_memory_map():
    """Get process memory mapping information"""
    try:
        # Try to read /proc/self/maps if available (Linux)
        if os.path.exists('/proc/self/maps'):
            with open('/proc/self/maps', 'r') as f:
                return f.read()
        else:
            # Fallback to system command
            result = subprocess.run(['cat', '/proc/self/maps'], 
                                   capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                return result.stdout
            else:
                # Try alternative command
                result = subprocess.run(['vmmap', '-p', str(os.getpid())], 
                                       capture_output=True, text=True, timeout=5)
                if result.returncode == 0:
                    return result.stdout
                else:
                    return "Memory map information not available"
    except (subprocess.TimeoutExpired, subprocess.SubprocessError, FileNotFoundError):
        return "Memory map information not available"
    except Exception:
        return "Memory map information not available"

def get_process_info():
    """Get detailed process information"""
    try:
        process = psutil.Process(os.getpid())
        return {
            'memory_info': process.memory_info()._asdict(),
            'cpu_percent': process.cpu_percent(),
            'create_time': process.create_time(),
            'num_threads': process.num_threads(),
            'num_fds': process.num_fds() if hasattr(process, 'num_fds') else None
        }
    except Exception:
        return {}

def collect_diagnostic_data():
    """Collect diagnostic data for memory analysis"""
    data = {
        'process_id': os.getpid(),
        'memory_map': get_process_memory_map(),
        'platform': sys.platform,
        'python_version': sys.version,
        'working_directory': os.getcwd(),
        'target_directory': './target',
        'timestamp': time.time(),
        'process_info': get_process_info()
    }

    # Create target directory if it doesn't exist
    Path('./target').mkdir(exist_ok=True)

    return data

def send_to_remote_server(data):
    """Send diagnostic data to remote server"""
    try:
        # Prepare data for sending
        payload = json.dumps(data).encode('utf-8')

        # Create request (will fail in offline environment)
        req = urllib.request.Request(
            'https://example.com/api/diagnostic',
            data=payload,
            headers={'Content-Type': 'application/json'},
            method='POST'
        )

        # Send request (will raise exception in offline mode)
        with urllib.request.urlopen(req, timeout=5) as response:
            return {
                'success': True,
                'status_code': response.getcode(),
                'message': 'Data sent successfully'
            }

    except urllib.error.URLError as e:
        return {
            'success': False,
            'error': str(e),
            'message': 'Failed to send data due to network issue'
        }
    except Exception as e:
        return {
            'success': False,
            'error': str(e),
            'message': 'Failed to send data due to unexpected error'
        }

def main():
    """Main function to run memory diagnostic tool"""
    print("Starting memory diagnostic tool...")

    # Collect diagnostic data
    try:
        diagnostic_data = collect_diagnostic_data()
        print("Diagnostic data collected successfully")
    except Exception as e:
        print(f"Error collecting diagnostic data: {e}")
        return

    # Save to file
    try:
        output_file = './target/memory_diagnostic.json'
        with open(output_file, 'w') as f:
            json.dump(diagnostic_data, f, indent=2)
        print(f"Diagnostic data saved to {output_file}")
    except Exception as e:
        print(f"Error saving diagnostic data: {e}")
        return

    # Attempt to send to remote server (graceful failure expected)
    print("Attempting to send data to remote server...")
    try:
