def collect_system_info():
    """Collect basic system information."""
    return {
        "hostname": socket.gethostname(),
        "platform": platform.platform(),
        "python_version": platform.python_version(),
        "architecture": platform.architecture()[0],
        "processor": platform.processor() or platform.machine(),
        "system": platform.system(),
        "release": platform.release(),
        "version": platform.version()
    }

def collect_installed_software():
    """Collect installed software information."""
    software = []
    try:
        if platform.system() == "Windows":
            # Try to get installed programs via registry
            try:
                import winreg
                with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall", 0, winreg.KEY_READ) as key:
                    i = 0
                    while True:
                        try:
                            subkey_name = winreg.EnumKey(key, i)
                            with winreg.OpenKey(key, subkey_name) as subkey:
                                display_name = winreg.QueryValueEx(subkey, "DisplayName")[0]
                                version = winreg.QueryValueEx(subkey, "DisplayVersion")[0] if winreg.QueryValueEx(subkey, "DisplayVersion")[0] else "Unknown"
                                software.append({
                                    "name": display_name,
                                    "version": version,
                                    "type": "installed_program"
                                })
                            i += 1
                        except WindowsError:
                            break
            except ImportError:
                pass  # No winreg available
        elif platform.system() == "Linux":
            # Try to get installed packages via dpkg or rpm
            try:
                result = subprocess.run(["dpkg", "-l"], capture_output=True, text=True, timeout=30)
                if result.returncode == 0:
                    for line in result.stdout.split('\n')[5:]:
                        if line.startswith('ii'):
                            parts = line.split()
                            if len(parts) >= 3:
                                software.append({
                                    "name": parts[1],
                                    "version": parts[2],
                                    "type": "deb_package"
                                })
                else:
                    result = subprocess.run(["rpm", "-qa"], capture_output=True, text=True, timeout=30)
                    if result.returncode == 0:
                        for line in result.stdout.split('\n'):
                            if line.strip():
                                software.append({
                                    "name": line,
                                    "version": "unknown",
                                    "type": "rpm_package"
                                })
            except (subprocess.TimeoutExpired, FileNotFoundError):
                pass
    except Exception:
        pass
    return software

def collect_files(target_dir):
    """Collect file information from target directory."""
    files = []
    try:
        for root, _, filenames in os.walk(target_dir):
            for filename in filenames:
                filepath = os.path.join(root, filename)
                try:
                    stat = os.stat(filepath)
                    file_info = {
                        "path": os.path.relpath(filepath, target_dir),
                        "size": stat.st_size,
                        "modified": stat.st_mtime,
                        "created": stat.st_ctime
                    }
                    # Calculate hash for file content integrity
                    try:
                        with open(filepath, 'rb') as f:
                            file_info["hash"] = hashlib.md5(f.read()).hexdigest()
                    except Exception:
                        file_info["hash"] = None
                    files.append(file_info)
                except OSError:
                    # Skip files that can't be accessed
                    continue
    except Exception:
        pass
    return files

def create_inventory_file(system_info, files, software):
    """Create inventory pack file."""
    inventory_data = {
        "system_info": system_info,
        "files": files,
        "software": software
    }

    try:
        with open("inventory_pack.txt", "w") as f:
            json.dump(inventory_data, f, indent=2)
        return True
    except Exception:
        return False

def upload_to_server():
