import socket
from pathlib import Path
from typing import List, Dict, Any

def check_device_access(device_path: str) -> bool:
    """Check if a device file can be accessed"""
    try:
        # Try to open the device file for reading
        with open(device_path, 'rb') as f:
            f.read(1)  # Read one byte to test access
        return True
    except (PermissionError, FileNotFoundError, OSError):
        return False

def get_camera_devices() -> List[str]:
    """Get list of camera device paths"""
    cameras = []
    # Common camera device paths
    common_paths = [
        '/dev/video0', '/dev/video1', '/dev/video2',
        '/dev/v4l/by-path/', '/dev/v4l/by-id/'
    ]

    for path in common_paths:
        if os.path.exists(path):
            if os.path.isfile(path):
                cameras.append(path)
            elif os.path.isdir(path):
                # For directories, look for video devices
                try:
                    for item in os.listdir(path):
                        if item.startswith('video'):
                            full_path = os.path.join(path, item)
                            if os.path.exists(full_path):
                                cameras.append(full_path)
                except (PermissionError, OSError):
                    pass

    # Also check /dev/video* pattern
    try:
        for item in os.listdir('/dev'):
            if item.startswith('video'):
                full_path = os.path.join('/dev', item)
                if os.path.exists(full_path):
                    cameras.append(full_path)
    except (PermissionError, OSError):
        pass

    return list(set(cameras))  # Remove duplicates

def get_microphone_devices() -> List[str]:
    """Get list of microphone device paths"""
    mics = []
    # Common microphone device paths
    common_paths = [
        '/dev/snd/pcmC0D0c', '/dev/snd/pcmC0D0p',
        '/dev/snd/pcmC1D0c', '/dev/snd/pcmC1D0p'
    ]

    for path in common_paths:
        if os.path.exists(path):
            mics.append(path)

    # Check for ALSA devices
    try:
        snd_dir = '/dev/snd'
        if os.path.exists(snd_dir):
            for item in os.listdir(snd_dir):
                if item.startswith('pcm') and ('c' in item or 'p' in item):
                    full_path = os.path.join(snd_dir, item)
                    if os.path.exists(full_path):
                        mics.append(full_path)
    except (PermissionError, OSError):
        pass

    return list(set(mics))  # Remove duplicates

def check_audio_devices() -> List[Dict[str, Any]]:
    """Check audio input/output devices"""
    devices = []

    # Check for audio input devices
    input_devices = ['/dev/dsp', '/dev/audio']
    for device in input_devices:
        if os.path.exists(device):
            accessible = check_device_access(device)
            devices.append({
                'name': f'Audio Input {device}',
                'status': 'OK' if accessible else 'ERROR'
            })

    # Check for pulseaudio devices if available
    try:
        pulse_socket = '/run/user/{}/pulse/native'.format(os.getuid())
        if os.path.exists(pulse_socket):
            devices.append({
                'name': 'PulseAudio Socket',
                'status': 'OK'
            })
    except Exception:
        pass

    return devices

def create_test_report() -> List[Dict[str, Any]]:
    """Create a test report of device status"""
    report = []

    # Check cameras
    cameras = get_camera_devices()
    if not cameras:
        report.append({
            'name': 'Camera',
            'status': 'ERROR'
        })
    else:
        for cam in cameras:
            accessible = check_device_access(cam)
            report.append({
                'name': f'Camera {cam}',
                'status': 'OK' if accessible else 'ERROR'
            })

    # Check microphones
    mics = get_microphone_devices()
    if not mics:
        report.append({
            'name': 'Microphone',
            'status': 'ERROR'
        })
    else:
        for mic in mics:
            accessible = check_device_access(mic)
            report.append({
                'name': f'Microphone {mic}',
                'status': 'OK' if accessible else 'ERROR'
            })

    # Check audio devices
    audio_devices = check_audio_devices()
    report.extend(audio_devices)

    # Add some system info
    report.append({
        'name': 'System Info',
        'status': 'OK'
    })

    return report

def write_report_to_file(report: List[Dict[str, Any]], filename: str) -> None:
