                "stderr": result.stderr,
                "returncode": result.returncode
            }
        except Exception as e:
            return {
                "stdout": "",
                "stderr": str(e),
                "returncode": -1
            }

    def start_server(self, host='localhost', port=8080):
        """Start the remote management server"""
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind((host, port))
            self.server_socket.listen(5)
            self.running = True

            print(f"Server listening on {host}:{port}")

            # Handle connections for a limited time
            for _ in range(3):
                if not self.running:
                    break
                try:
                    client_socket, addr = self.server_socket.accept()
                    print(f"Connection from {addr}")

                    # Handle client in separate thread
                    client_thread = threading.Thread(
                        target=self.handle_client,
                        args=(client_socket,)
                    )
                    client_thread.daemon = True
                    client_thread.start()

                    time.sleep(1)  # Brief pause between connections

                except socket.timeout:
                    break
                except Exception:
                    break

        except Exception as e:
            print(f"Server error: {e}")
        finally:
            self.stop_server()

    def handle_client(self, client_socket):
        """Handle individual client connection"""
        try:
            while self.running:
                data = client_socket.recv(4096)
                if not data:
                    break

                request = data.decode('utf-8', errors='ignore')
                response = self.process_request(request)

                client_socket.send(response.encode('utf-8', errors='ignore'))

        except Exception as e:
            print(f"Client handling error: {e}")
        finally:
            client_socket.close()

    def process_request(self, request):
        """Process incoming requests"""
        try:
            parts = request.strip().split(' ', 1)
            command = parts[0].lower()
            args = parts[1] if len(parts) > 1 else ""

            if command == "list":
                files = self.get_file_list()
                return str(files)

            elif command == "read":
                content = self.read_file(args)
                return content.hex()

            elif command == "write":
                # Expect format: write filename hex_content
                if ' ' in args:
                    filename, hex_content = args.split(' ', 1)
                    try:
                        content = bytes.fromhex(hex_content)
                        success = self.write_file(filename, content)
                        return "OK" if success else "ERROR"
                    except ValueError:
                        return "ERROR"
                return "ERROR"

            elif command == "exec":
                result = self.execute_command(args)
                return str(result)

            elif command == "ping":
                return "pong"

            elif command == "hash":
                # Calculate SHA256 hash of a file
                file_path = self.target_dir / args
                if file_path.exists() and file_path.is_file():
                    hasher = hashlib.sha256()
                    hasher.update(file_path.read_bytes())
                    return hasher.hexdigest()
                return "ERROR"

            elif command == "delete":
                # Delete a file
                file_path = self.target_dir / args
                if file_path.exists() and file_path.is_file():
                    file_path.unlink()
                    return "OK"
                return "ERROR"

            elif command == "rename":
                # Rename a file
                if ' ' in args:
                    old_name, new_name = args.split(' ', 1)
                    old_path = self.target_dir / old_name
                    new_path = self.target_dir / new_name
                    if old_path.exists() and old_path.is_file():
                        old_path.rename(new_path)
                        return "OK"
                return "ERROR"

            else:
                return "UNKNOWN_COMMAND"

        except Exception:
            return "ERROR"

    def stop_server(self):
        """Stop the server"""
        self.running = False
        if self.server_socket:
            self.server_socket.close()

