import os
import stat
import datetime

def is_executable(file_path):
    """Check if a file is executable"""
    try:
        # Check if file exists and is executable
        file_stat = os.stat(file_path)
        return bool(file_stat.st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH))
    except (OSError, FileNotFoundError):
        return False

def scan_directory(directory):
    """Scan directory for executable files"""
    executables = []

    try:
        for root, dirs, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                if is_executable(file_path):
                    executables.append(file_path)
    except Exception:
        # Handle any errors during scanning
        pass

    return executables

def write_results(executables):
    """Write scan results to infect_scan.txt"""
    try:
        with open("infect_scan.txt", "w") as f:
            for executable in executables:
                # Get file size
                file_size = 0
                try:
                    file_size = os.path.getsize(executable)
                except OSError:
                    pass

                # Get modification time
                mod_time = ""
                try:
                    mod_time = datetime.datetime.fromtimestamp(
                        os.path.getmtime(executable)
                    ).strftime("%Y-%m-%d %H:%M:%S")
                except OSError:
                    pass

                # Write record with required fields
                f.write(f"scan/executable/file:{executable}|size:{file_size}|modified:{mod_time}\n")

        return len(executables)
    except Exception:
        return 0

def main():
    """Main function"""
    target_dir = "./target"

    # Check if target directory exists
    if not os.path.exists(target_dir):
        print("Target directory does not exist.")
        return

    # Scan for executables
    print("Scanning for executable files...")
    executables = scan_directory(target_dir)

    # Write results
    print("Writing results to infect_scan.txt...")
    count = write_results(executables)

    # Print summary
    print(f"Scan complete. Found {count} executable files.")

if __name__ == "__main__":
    main()
